<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';import { ElMessage } from 'element-plus';import { listIOTMessages,listIOTTopics,publishIOTMessage,type IOTMessage,type IOTTopic } from '@/api/iot'
const topic=ref(''),payload=ref(''),qos=ref(0),retain=ref(false),sending=ref(false),messages=ref<IOTMessage[]>([]),topics=ref<IOTTopic[]>([])
async function load(){const[m,t]=await Promise.all([listIOTMessages({page:1,limit:100}),listIOTTopics({page:1,limit:1000})]);messages.value=[...m.data.data.list].reverse();topics.value=t.data.data.list}
async function publish(){if(!topic.value.trim()){ElMessage.warning('请输入 Topic');return};sending.value=true;try{await publishIOTMessage({topic:topic.value.trim(),payload:payload.value,qos:qos.value,retain:retain.value});ElMessage.success('消息已发送');await load()}finally{sending.value=false}}
let refreshTimer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await load();refreshTimer=setInterval(()=>void load(),3000)})
onBeforeUnmount(()=>{if(refreshTimer)clearInterval(refreshTimer)})
</script>
<template><section class="mqtt-page"><header><h1>消息收发</h1><el-button @click="load">刷新</el-button></header><main><section class="feed"><div v-if="!messages.length" class="empty">暂无消息</div><article v-for="m in messages" :key="m.id"><small>{{m.topic}} · QoS {{m.qos}} · {{String(m.received_at).replace('T',' ').slice(0,19)}}</small><pre>{{m.payload}}</pre></article></section><aside><el-form label-position="top"><el-form-item label="发布 Topic"><el-select v-model="topic" filterable allow-create default-first-option placeholder="选择或输入 Topic"><el-option v-for="t in topics" :key="t.id" :label="t.topic" :value="t.topic"/></el-select></el-form-item><el-form-item label="消息内容"><el-input v-model="payload" type="textarea" :rows="10" placeholder="输入消息内容"/></el-form-item><div class="options"><el-select v-model="qos"><el-option v-for="v in [0,1,2]" :key="v" :label="`QoS ${v}`" :value="v"/></el-select><label>保留消息 <el-switch v-model="retain"/></label></div><el-button type="primary" :loading="sending" @click="publish">发送消息</el-button></el-form></aside></main></section></template>
<style scoped>.mqtt-page{height:100%;min-width:0;display:flex;flex-direction:column;gap:8px;padding:0 8px;box-sizing:border-box;font-size:11px}.mqtt-page header{display:flex;align-items:center;justify-content:space-between}.mqtt-page h1{margin:0;font-size:18px}.mqtt-page main{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:8px}.feed,aside{min-width:0;border:1px solid var(--line);border-radius:8px;padding:10px;overflow:auto;background:#fff}.feed article{margin-bottom:8px;padding:8px;border-radius:7px;background:#f7f8fb}.feed small{color:var(--text-secondary)}.feed pre{margin:6px 0 0;white-space:pre-wrap;word-break:break-word}.empty{text-align:center;color:var(--text-secondary);padding:40px}.options{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.options .el-select{width:100px}aside .el-select{width:100%}@media(max-width:760px){.mqtt-page main{grid-template-columns:1fr}}</style>
